import sys
from datetime import datetime

def minutes(text):
    h, m = text.split(":")
    return int(h) * 60 + int(m)


def calculate_blocks(duration_minutes):
    blocks = duration_minutes // 60 + 1
    return min(blocks, 24)


def calculate_period_price(blocks):
    if blocks <= 24:
        if 8 <= blocks <= 20:
            return blocks * 2.5
        else:
            return blocks * 1.0
    else:
        return 18.0


def main():
    totals = {}
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) < 4:
            print(f"{parts[0]} invalid")
            continue
        plate = parts[0]
        entry_date = parts[1]
        entry_time = parts[2]
        exit_date = parts[3]
        exit_time = parts[4]

        try:
            entry = datetime.strptime(f"{entry_date} {entry_time}", "%Y-%m-%d %H:%M")
            exit = datetime.strptime(f"{exit_date} {exit_time}", "%Y-%m-%d %H:%M")
        except ValueError:
            print(f"{plate} invalid")
            continue

        duration = (exit - entry).total_seconds() / 60
        if duration < 0:
            print(f"{plate} invalid")
            continue

        if duration <= 30:
            fee = 0.0
        else:
            blocks = calculate_blocks(duration)
            fee = calculate_period_price(blocks)

        totals[plate] = totals.get(plate, 0) + fee
        print(f"{plate} {duration // 60}:{duration % 60:02d} {fee:.2f}")

    print("---")
    for plate in sorted(totals, key=lambda x: (-totals[x], x)):
        print(f"{plate} {totals[plate]:.2f}")


if __name__ == "__main__":
    main()
